INSERT INTO products (product_id, category_id, manufacturer_id, subcategory, product_name, image_path, description, composition, price) VALUES (28, 3, 16, 'Туфли', 'Туфли из натуральной кожи', 'IMG_MSho_191612.png', 'Модель выполнена из натуральной кожи, на резиновой подошве, поддеживает классический и деловой стиль образов. Производитель: Дом обуви «Берестов», г. Москва', 'Верх — натуральная кожа, подкладка — натуральная кожа, стелька — натуральная кожа, подошва — резина', 25625);
